<script setup lang="ts">
import {ref,watch,computed} from 'vue'
import {NButton,NInput,NModal,NSelect} from 'naive-ui'
import {money,type Account} from '../api/funds'
import {membersApi,type Member,type Claim,type RepaymentInput,type RepaymentPreview} from '../api/memberClaims'
import EndpointSelector from './EndpointSelector.vue'
const props=defineProps<{show:boolean;member:Member;accounts:Account[];claims:Claim[]}>()
const emit=defineEmits<{close:[];saved:[]}>()
const fresh=():RepaymentInput=>({member_id:props.member.id,source_account_id:'',amount:'',effective_date:new Date().toLocaleDateString('sv-SE'),description:'',basis:'',allocation_mode:'oldest_first'})
const form=ref(fresh()),manual=ref<Record<string,string>>({}),preview=ref<RepaymentPreview|null>(null),busy=ref(false),error=ref(''),stamp=ref('')
const input=computed<RepaymentInput>(()=>({...form.value,...form.value.allocation_mode==='manual'?{allocations:Object.entries(manual.value).filter(([,amount])=>amount.trim()).map(([claim_id,amount])=>({claim_id,amount}))}:{}}))
const valid=computed(()=>preview.value&&stamp.value===JSON.stringify(input.value))
watch(input,()=>{preview.value=null},{deep:true})
watch(()=>props.show,show=>{if(show){form.value=fresh();manual.value={};preview.value=null;error.value=''}})
async function runPreview(){if(busy.value)return;busy.value=true;error.value='';preview.value=null;const payload={...input.value},current=JSON.stringify(payload);try{const result=await membersApi.preview(payload);if(JSON.stringify(input.value)===current){preview.value=result;stamp.value=current}}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function save(){if(busy.value||!valid.value)return;busy.value=true;error.value='';const body={...input.value,allocations:preview.value!.allocations};try{await membersApi.submitRepayment(body);emit('saved');emit('close')}catch(e){preview.value=null;error.value=(e as Error).message+'。请查看偿还记录，重新提交前需再次预览。'}finally{busy.value=false}}
</script>
<template><NModal :show="show" preset="card" title="偿还成员垫付" class="dialog" @close="emit('close')"><p>收款成员：{{member.name}}（{{member.account_id}}）</p><EndpointSelector v-model="form.source_account_id" :accounts="accounts.filter(a=>a.is_fund)" label="付款资金账户" :disabled="busy"/><label>付款金额（元）<NInput v-model:value="form.amount" :disabled="busy"/></label><label>业务日期<input v-model="form.effective_date" type="date" :disabled="busy"></label><label>付款依据<NInput v-model:value="form.basis" :disabled="busy"/></label><label>说明<NInput v-model:value="form.description" :disabled="busy"/></label><label>匹配方式<NSelect v-model:value="form.allocation_mode" :disabled="busy" :options="[{label:'按确认时间先后匹配',value:'oldest_first'},{label:'手动指定每笔金额',value:'manual'}]"/></label><template v-if="form.allocation_mode==='manual'"><label v-for="claim in claims.filter(c=>c.outstanding_minor>0)" :key="claim.id">{{claim.transfer.effective_date}}，未结 ¥{{money(claim.outstanding_minor)}}（{{claim.id}}）<NInput :value="manual[claim.id]||''" :disabled="busy" placeholder="本次偿还金额（元），留空不匹配" @update:value="manual[claim.id]=$event"/></label></template><div v-if="preview" class="preview"><strong>付款 ¥{{money(preview.amount_minor)}}，资金账户减少相同金额</strong><table><thead><tr><th>垫付编号</th><th>本次匹配（元）</th></tr></thead><tbody><tr v-for="a in preview.allocations" :key="a.claim_id"><td>{{a.claim_id}}</td><td>{{a.amount}}</td></tr></tbody></table></div><p v-if="error" class="error">{{error}}</p><div class="actions"><NButton :disabled="busy" :loading="busy" @click="runPreview">预览匹配</NButton><NButton type="primary" :disabled="busy||!valid" :loading="busy" @click="save">确认付款</NButton></div></NModal></template>
